 String money(double x){return String.format(Locale.US,"%,.0f",x);} String words(long n){String[] u={"صفر","یک","دو","سه","چهار","پنج","شش","هفت","هشت","نه","ده","یازده","دوازده","سیزده","چهارده","پانزده","شانزده","هفده","هجده","نوزده","بیست","بیست و یک","بیست و دو","بیست و سه","بیست و چهار","بیست و پنج","بیست و شش","بیست و هفت","بیست و هشت","بیست و نه"};String[] t={"","","بیست","سی","چهل","پنجاه","شصت","هفتاد","هشتاد","نود"};String[] h={"","","صد","دویست","سیصد","چهارصد","پانصد","ششصد","هفتصد","هشتصد","نهصد"};if(n<30)return u[(int)n];if(n<100)return t[(int)n/10]+(n%10>0?" و "+u[(int)n%10]:"");if(n<1000)return h[(int)n/100]+(n%100>0?" و "+words(n%100):"");if(n<1000000)return words(n/1000)+" هزار"+(n%1000>0?" و "+words(n%1000):"");if(n<1000000000)return words(n/1000000)+" میلیون"+(n%1000000>0?" و "+words(n%1000000):"");return words(n/1000000000)+" میلیارد"+(n%1000000000>0?" و "+words(n%1000000000):"");} String amountWords(double v){return words(Math.round(v))+" ریال";} 
 double num(EditText e){try{return Double.parseDouble(e.getText().toString().replace(",",""));}catch(Exception x){return 0;}}
 double expenseSum(JSONObject m,String cat){double s=0;JSONArray a=m.optJSONArray("expenses");if(a!=null)for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(cat==null||cat.equals(o.optString("category")))s+=o.optDouble("amount");}return s;}
 double missionPay(JSONObject m){double d=m.optDouble("days",1),h=m.optDouble("holiday",0);if(m.optBoolean("suburb"))return d*SUBURB+h*HOLIDAY;return (d==1?DAILY:d*MULTI)+h*HOLIDAY;} double reimbursable(JSONObject m,String payerKey,String amountKey){return "شخص".equals(payer(m,payerKey))?m.optDouble(amountKey):0;} double total(JSONObject m){return missionPay(m)+reimbursable(m,"hotelPayer","hotel")+reimbursable(m,"goPayer","ticketGo")+reimbursable(m,"backPayer","ticketBack")+reimbursable(m,"cancelGoPayer","cancelGo")+reimbursable(m,"cancelBackPayer","cancelBack")+expenseSum(m,null);} String payer(JSONObject m,String key){return m.optString(key,"شخص");} int[] gregorianToJalali(int gy,int gm,int gd){int[] gdm={0,31,28,31,30,31,30,31,31,30,31,30,31};int gy2=gy-1600,gm2=gm-1,gd2=gd-1;int gdn=365*gy2+(gy2+3)/4-(gy2+99)/100+(gy2+399)/400;for(int i=0;i<gm2;i++)gdn+=gdm[i];if(gm2>1&&((gy%4==0&&gy%100!=0)||gy%400==0))gdn++;gdn+=gd2;int jdn=gdn-79;int j_np=jdn/12053;jdn%=12053;int jy=979+33*j_np+4*(jdn/1461);jdn%=1461;if(jdn>=366){jy+=(jdn-1)/365;jdn=(jdn-1)%365;}int jm=jdn<186?1+jdn/31:7+(jdn-186)/30;int jd=1+(jdn% (jdn<186?31:30));return new int[]{jy,jm,jd};}
int days360(int sy,int sm,int sd,int ey,int em,int ed){if(sd==31)sd=30;if(ed==31&&(sd==30||sd==31))ed=30;return 360*(ey-sy)+30*(em-sm)+(ed-sd);}
void validate7(String end){if(end==null||end.trim().isEmpty())return;try{String[] p=end.trim().replace("-","/").split("/");if(p.length!=3)return;int y=Integer.parseInt(p[0]),mo=Integer.parseInt(p[1]),da=Integer.parseInt(p[2]);int[] now=gregorianToJalali(Calendar.getInstance().get(Calendar.YEAR),Calendar.getInstance().get(Calendar.MONTH)+1,Calendar.getInstance().get(Calendar.DAY_OF_MONTH));int d;if(y>=1200&&y<1700)d=days360(y,mo,da,now[0],now[1],now[2]);else{Calendar e=Calendar.getInstance();e.setLenient(false);e.set(y,mo-1,da,0,0,0);e.getTime();Calendar n=Calendar.getInstance();n.set(Calendar.HOUR_OF_DAY,0);n.set(Calendar.MINUTE,0);n.set(Calendar.SECOND,0);n.set(Calendar.MILLISECOND,0);d=(int)((n.getTimeInMillis()-e.getTimeInMillis())/86400000L);}if(d>7)throw new IllegalArgumentException("بیشتر از 7 روز از مأموریت گذشته و هزینه‌ها طبق Excel قابل پرداخت نیست");}catch(NumberFormatException x){}catch(IllegalArgumentException x){if(x.getMessage()!=null&&x.getMessage().contains("بیشتر از 7 روز"))throw x;}}
 void home(){base("مدیریت هزینه مأموریت");Button n=bt("＋ مأموریت جدید");n.setOnClickListener(v->{cur=new JSONObject();try{cur.put("expenses",new JSONArray());}catch(Exception e){}edit();});box.addView(n);ScrollView sc=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);for(JSONObject m:data){Button x=bt(m.optString("subject","بدون موضوع")+" | "+m.optString("destination","")+" | "+money(total(m))+" ریال");x.setOnClickListener(v->{cur=m;edit();});list.addView(x);}sc.addView(list);box.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
