  add("هتل",hotel);add("پرداخت هتل توسط",hp);add("بلیط رفت",go);add("پرداخت بلیط رفت توسط",gp);add("شماره بلیط رفت",goNo);add("بلیط برگشت",back);add("پرداخت بلیط برگشت توسط",bp);add("شماره بلیط برگشت",backNo);add("کنسلی بلیط رفت",cancelGo);add("پرداخت کنسلی رفت توسط",cgp);add("کنسلی بلیط برگشت",cancelBack);add("پرداخت کنسلی برگشت توسط",cbp);
