 void expenseDialog(LinearLayout list,TextView sum){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);Spinner cat=spinner(cats);Spinner ti=spinner(tehranItems);cat.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){ti.setVisibility(pos==0?View.VISIBLE:View.GONE);}public void onNothingSelected(android.widget.AdapterView<?> p){}});EditText date=ed("تاریخ"),desc=ed("شرح"),invoice=ed("شماره فاکتور"),amount=ed("مبلغ");l.addView(cat);l.addView(ti);l.addView(date);l.addView(desc);l.addView(invoice);l.addView(amount);new AlertDialog.Builder(this).setTitle("افزودن هزینه").setView(l).setNegativeButton("انصراف",null).setPositiveButton("ثبت",(d,w)->{try{JSONArray a=cur.getJSONArray("expenses");JSONObject o=new JSONObject();o.put("category",cat.getSelectedItem().toString());o.put("tehranItem",ti.getSelectedItem().toString());o.put("date",date.getText().toString());o.put("desc",desc.getText().toString());o.put("invoice",invoice.getText().toString());o.put("amount",num(amount));a.put(o);render(list,sum);}catch(Exception e){toast(e.getMessage());}}).show();}
 void render(LinearLayout list,TextView sum){list.removeAllViews();JSONArray a=cur.optJSONArray("expenses");if(a!=null)for(int i=0;i<a.length();i++){final int k=i;JSONObject o=a.optJSONObject(i);Button x=bt(o.optString("category")+" | "+o.optString("desc")+" | "+money(o.optDouble("amount"))+" ریال  ✕");x.setOnClickListener(v->{a.remove(k);render(list,sum);});list.addView(x);}sum.setText("جمع کل: "+money(total(cur))+" ریال");}
 void save(){try{JSONArray a=new JSONArray();for(JSONObject m:data)a.put(m);getPreferences(0).edit().putString("data",a.toString()).apply();}catch(Exception e){}}
