  if(ar!=null)for(int i=0;i<ar.length()&&y<730;i++){JSONObject o=ar.optJSONObject(i);String cat=o.optString("category");String[] rr={cat,o.optString("desc"),o.optString("date"),o.optString("invoice"),money(o.optDouble("amount"))};q.setStyle(Paint.Style.STROKE);c.drawRect(margin,y,W-margin,y+28,q);for(int z=1;z<tx.length-1;z++)c.drawLine(tx[z],y,tx[z],y+28,q);q.setStyle(Paint.Style.FILL);for(int z=0;z<5;z++)drawRtl(c,rr[z],tx[z],y+6,tx[z+1]-tx[z],18,q);for(int z=0;z<cn.length;z++)if(cn[z].equals(cat))sums[z]+=o.optDouble("amount");y+=28;}
